layer.css:
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: #8c9098; border-radius: 12px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 8px; padding-bottom: 0px; padding-left: 8px; transition: 0.2s }
[data-ryt="header"] { background-image: linear-gradient(rgb(0, 51, 77), rgb(51, 92, 112)); background-size: auto; background-position: 0% 0%; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] a { color: #8c9098; border-radius: 4px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.294s, border-color 0.294s, color 0.294s }
[data-ryt="rec-card"] [data-ryt="title"] { color: #8c9098; border-radius: 4px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.294s, border-color 0.294s, color 0.294s }
[data-ryt="nav"] a:hover { background-color: rgb(102, 133, 148) }
